INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c7b93b38-27eb-4901-9f76-a478d631e74b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$41. óra: Összetett műveletek, zárójelfelbontás$q$, $q$Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "44738985-3602-4031-acb6-3eb5456e8724", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "0092651d-8955-4a11-836b-d455b02dfaa9", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "547129e4-ce25-4464-949f-32bc3d1c672e", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "880f706b-b2cd-40dd-9852-a51f32b54f4a", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "a5d65810-2a72-4e44-9f67-fdefa315527b", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "24c86812-3a4a-43e7-8ce3-4a4d82741b78", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "639d32f9-edb5-4ecc-bdcb-242db64a83e8", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "df038109-fdf7-4f54-9d2f-1e33aa8940f1", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "15045831-91ed-43ff-9677-4996681adbbf", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "6debdb03-14b7-4e4c-a036-18ff062b966d", "text": "Igaz", "isCorrect": true}, {"id": "46db95c7-eb2f-4177-97bf-26ad2f906d78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b8f30dd0-a55b-4c10-8962-2eeb4333e0d8", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "6df501d4-3ada-4783-a1f0-706cc1e3e499", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('df6fcdbe-accc-4000-b9a4-fd3cd74d126b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$42. óra: Összetett műveletek, zárójelfelbontás gyakorlása$q$, $q$Gyakorlás feladatlapok és összetett kifejezések segítségével.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "97b60763-d7cf-41d6-8819-e3f7ce8803ef", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "2bfe97e3-aa00-4301-8b9a-03b496a3ee5d", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "c92d70ea-27d2-4dbb-976c-6d369c8b8935", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "e7d17be9-1d74-4411-92bc-fc9221ad0678", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "089c8e09-3785-452a-aa1c-36684b937bb5", "text": "Igaz", "isCorrect": true}, {"id": "2e6abddb-ae54-4e91-8ed0-1b63e1bb9c99", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6909c41b-5184-48a6-ae88-585ddb332893", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "803181d4-e494-43b8-b557-51e477f0d58c", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "cd51587c-7cc3-41b1-b726-eeb22fd712bc", "text": "Igaz", "isCorrect": true}, {"id": "a93c1320-f6a4-44c6-948f-8252a6f28a2e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5792f651-4d42-4c4a-a734-5074f9c81abc", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ad632552-75aa-4c10-985e-6df8846c7241', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$43. óra: Összefoglalás$q$, $q$A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "1792465c-148a-42f1-9049-6c23144f4e75", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "116b4a58-f7f5-4d07-bea2-cd75f08be217", "text": "3/5", "isCorrect": true}, {"id": "20afe0a1-63c9-42f4-9e1c-2b5790c11ad8", "text": "12/20", "isCorrect": false}, {"id": "891662bb-3374-40b4-9079-92ab5f7f96dc", "text": "7/9", "isCorrect": false}, {"id": "36534a95-2662-4b52-a236-f94e32abae81", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "3d9b0c06-e372-41ed-bcd1-c4389d945453", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "7a6e205b-9404-4799-bb2f-2744dfb1e1c1", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "bc1e266a-4e3b-49dd-a5af-5ea692a0f82c", "text": "1/6", "isCorrect": false}, {"id": "a2d372a4-76a3-4e70-8fbd-20548ca922d5", "text": "2/3", "isCorrect": false}, {"id": "dcef8d11-65bf-4cd8-8319-832800076539", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "7cfd09f0-ad90-447b-8266-b5723c19e1f4", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a3e0029b-f5cd-47b0-bf2a-ab7ad1fa2c3c", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "c7e4bb80-db8e-4dce-9c0e-4558e135bf1a", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "d96266e8-adf2-43c3-9ae9-0c72ed8a0094", "text": "Igaz", "isCorrect": true}, {"id": "05743ef3-245e-4fb5-8acb-d4aa13d2771c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1d074037-0508-4aec-9d20-487c1f0cba91", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c8d9142d-f0fa-4043-881c-69cdcf15c05a", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('344f4949-9a60-4237-bfb2-663aab470aa5', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$44. óra: Feladatmegoldás$q$, $q$Gyakorló feladatok megbeszélése egyéni és csoportmunkában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "0e94096b-3f9c-4d59-8887-4d0597117ade", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "15dfcf42-84ea-4e3f-8720-5d09316000c5", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "a6cf9e2f-353e-4c32-94c3-1980b49da691", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "5c0506f5-01cc-4f5e-9ce8-b61be2b81ac3", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "6d1f73af-13a8-4a7a-9921-5ff359d219b2", "text": "1/5", "isCorrect": false}, {"id": "51dd4762-a942-437a-ad8c-8735daa4b2ce", "text": "1/2", "isCorrect": false}, {"id": "c3544514-c316-45dd-8be3-c5b0acdac8ed", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "0427c6bd-53f2-458f-9409-6dcd58178e77", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "33328081-0fd7-491e-85e0-514de859bd99", "text": "Igaz", "isCorrect": true}, {"id": "f6336492-2089-4da0-9b04-8b50f21fe3af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2976b58a-7c5c-4683-ade3-dcae3b12dc98", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "cb5d93d8-5edb-4f19-8993-67069e841d1d", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "b0b39c27-bd24-4ca5-8b68-c031def60bf9", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "ef44393c-5bae-491b-a85f-d1e47fea9e9b", "text": "Igaz", "isCorrect": true}, {"id": "9e2db506-843b-467b-b887-12f0276dce76", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
