5fc-4384-9b14-6e1743b229e1", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "a617acae-5772-4a03-b072-741f346c6f9a", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "e000e51e-8968-466a-8ee4-030f9c097d10", "text": "Igaz", "isCorrect": true}, {"id": "3eaed811-8525-4cd7-a389-51c753654aa2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
