 "9/4", "isCorrect": true}, {"id": "a9c8d66e-fc81-4f27-96db-7107bd4e00b2", "text": "-4/9", "isCorrect": false}, {"id": "2ad5474d-1a54-470f-9d91-53f6ba47918d", "text": "1/4", "isCorrect": false}, {"id": "e3c5caec-e767-4584-8755-45348eec478e", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "23d9c1f6-10e0-4118-a856-6988ebf1904b", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "a5a173ca-feb8-4962-939f-de92cda514de", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "d51e12c6-f520-46d6-8880-1756e21cb5d2", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4bad1d2a-dcf0-400c-9634-ed3daaf91ce3", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "0bcb1e20-0360-4012-b476-63a6aa77e6a6", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "8c1ece53-9d88-4105-b708-4272a7392dd3", "text": "Igaz", "isCorrect": true}, {"id": "ae98c63e-8eb3-4e0f-a007-1e6fce58b2c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "09504354-7680-4357-ad68-57b31135b937", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ce5c07f5-c6ea-4195-b790-347c9848b556', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$47. óra: Témazáró dolgozat értékelése$q$, $q$A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "c46615d1-c9a0-49b2-b85f-b97370e31211", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "6eaa05f4-a7bd-4bab-9146-2fecd6c2349e", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "2a80c609-159f-4d0e-ae37-1dcef37146cb", "text": "A számlálók leírása", "isCorrect": false}, {"id": "de41be91-205f-45f7-b017-76c85a076c61", "text": "A zárójel használata", "isCorrect": false}, {"id": "19f79395-fd3c-4845-86ef-03f3dd7378fd", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "49fe67ba-aee8-459c-9802-7bc4ccb72a9a", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "2accbed7-2f47-41aa-a494-c84927abb89a", "text": "Igaz", "isCorrect": true}, {"id": "53f5fcb8-c074-4145-a540-f292f502bfd3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3a96a686-bf96-4c8e-b195-3a3cc5020d1b", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "461705a3-e0ab-427c-bf02-ab7e3f7addce", "text": "2/5", "isCorrect": true}, {"id": "3a1191d4-45a2-4cf0-9046-08a0cd34cc24", "text": "4/10", "isCorrect": false}, {"id": "7982ab49-0ef0-4672-8010-df038a07aaa8", "text": "1/5", "isCorrect": false}, {"id": "6a90b6c0-d9c9-4e7c-ba56-fd39b8309461", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "dd982107-8aaa-4153-9afd-60cd092c0d18", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "f033d10d-297a-4bd7-bf6c-4de6bf2f21a7", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "c22dafae-296e-4c7c-82c2-f708d34b37b9", "text": "Igaz", "isCorrect": true}, {"id": "4a4ac92e-d0ab-47c4-8df2-a23022e9ad4a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "902d6bad-80d2-403a-8127-4f1b2977aa31", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "3ec846f1-bcef-4c99-bcbf-7f4a640843af", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('19961c0f-da28-4766-8dd4-e7169644c9f7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$48. óra: Síkbeli alakzatok$q$, $q$Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "7179efa4-ca57-4803-9804-7b0db8a0d486", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "0db351a6-c3ad-4090-a458-708afa09b460", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "71e1078b-4e84-4d2e-a322-c259aec377d3", "text": "Hegyesszög", "isCorrect": true}, {"id": "8be3785f-2f0d-4c3f-b826-8ea0358fdf42", "text": "Derékszög", "isCorrect": false}, {"id": "e29d0b16-db8f-4524-bebc-ca839e7d472d", "text": "Tompaszög", "isCorrect": false}, {"id": "cff44ae6-39f8-4dd3-a506-723d362473f9", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "bf43b08f-d5db-4a9d-8a4e-b4a697dbdbd4", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "6910d3be-131e-474f-8baf-c62859bd6c31", "text": "Derékszög", "isCorrect": true}, {"id": "d8d0afe2-9d78-499f-b8cf-b14b1b1ef04b", "text": "Hegyesszög", "isCorrect": false}, {"id": "a521b4c5-0f0b-4e84-88d4-440fff0acbe3", "text": "Tompaszög", "isCorrect": false}, {"id": "56b0463d-c31e-4f12-883a-80fc2f72195f", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "178111a2-e8af-49cb-873e-8b70aea0f498", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "ea7ac815-b61d-4951-9791-2255a2e1e05f", "text": "Tompaszög", "isCorrect": true}, {"id": "18ddec80-d128-45d2-ae56-d72b79e276eb", "text": "Hegyesszög", "isCorrect": false}, {"id": "afbee096-b830-4c6c-aff7-fddb13ed799e", "text": "Derékszög", "isCorrect": false}, {"id": "f57b44ce-6b99-409e-b8df-10eefed47145", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "edaf99e8-d4e8-4089-9f83-ae5a7aed6678", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "5a2860d4-8c01-4040-9abd-2fd73b9a3f7e", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "d376a248-5090-4467-821c-3635992eb075", "text": "Igaz", "isCorrect": true}, {"id": "1d3757cf-eb88-4647-9ba2-e70ff140ffa8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3dc61c4f-b3bf-4eda-9dd9-28ead8b8b7c1", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "97e09b72-7ac9-4ecb-87e8-4b6f6ac3fdc6", "text": "Igaz", "isCorrect": true}, {"id": "cf8b6699-e83a-464d-aa3b-6000c85ab8fb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2b6d362a-b615-49cb-bef2-df84897c5577', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$49. óra: Síkbeli alakzatok II.$q$, $q$Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "9c0834ab-056b-435e-997f-80c30ff74061", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "5a199d14-37f6-4548-8551-06bc27302c57", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "65e6b2c9-f7bb-4610-a5c8-ee50c7401ad4", "text": "Négyzet", "isCorrect": true}, {"id": "11bc6c56-030a-44f3-919b-11b591dc97f9", "text": "Rombusz", "isCorrect": false}, {"id": "fdf124a2-16f1-4586-ae61-2ec76525e423", "text": "Téglalap", "isCorrect": false}, {"id": "e8527bad-5279-43eb-a1c4-afc7429e7c0b", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "f47711a9-ac5a-45b0-af87-0c6e350a3e09", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "3215393b-1dd7-426e-be88-62a65da444f0", "text": "Rombusz", "isCorrect": true}, {"id": "9cfe57e5-400d-42d7-86ca-9c0dd0a04e62", "text": "Téglalap", "isCorrect": false}, {"id": "a64faf42-96da-4c37-9f6a-137acdc80773", "text": "Trapéz", "isCorrect": false}, {"id": "2d8dfefc-429c-4924-96b9-742f026cf3c5", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "b143a9f2-cf88-4bea-8622-787d3e44b853", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "b73e621d-e0ec-4f83-a208-c313d2aa215f", "text": "Igaz", "isCorrect": true}, {"id": "52e27820-1cd4-4ec6-8a86-d57063bb7a22", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "09615898-d174-44ee-a071-d61d0172bc05", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "5da688ef-845e-4d88-9ed4-a23b221db22f", "text": "Igaz", "isCorrect": true}, {"id": "f97a721c-4aa7-4b18-9818-9649887ed88f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca21e0ba-3afc-442a-b858-82f79125a755", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "c64faf1c-b241-47fa-ab3c-95a23056962b", "text": "Igaz", "isCorrect": true}, {"id": "f6c0cf50-85cc-44fa-977b-db9cbc429a91", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c0a57479-bf18-44fa-bfbf-0f78d475971f", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d5fae43c-cadd-4cf3-baca-227e7bf85c0b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$50. óra: Egybevágóság$q$, $q$Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "38c37c32-297c-47ff-af19-a49bafb504a3", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "0b650991-b47f-49fc-85a7-23c2ed2c25d3", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "10fd8660-d6b1-4b55-ae4d-2baa0aa52cb6", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "37c050d8-9453-4452-a336-00ac2f7a49d1", "text": "Ha a területük 0", "isCorrect": false}, {"id": "0cb6ac49-74ec-48bb-939b-880cabfab992", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "8d8f247b-bf12-4048-bcb4-93f29dfb0159", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "89510d2b-abb9-4dcf-a949-90660bb3329a", "text": "Igaz", "isCorrect": true}, {"id": "8c3b4247-966d-406b-8c91-1a82f3307f6a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "98d72ca1-db63-4448-97de-c257c7adab19", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "2455381d-f13a-4b92-90af-6b2695727437", "text": "Igaz", "isCorrect": true}, {"id": "f58a5871-8c98-4d2f-9d8a-45be6c06fd07", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4c318a7b-f653-4922-9dae-43954375833f", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "e4f2e865-928a-448e-8825-bd94f2bbddc7", "text": "Igaz", "isCorrect": false}, {"id": "60b80432-9502-498b-81c1-cd215eaa5e6f", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "8a83bac4-1334-49b9-9704-fe828a69af81", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "4eca1f58-47f9-4476-99a3-7503a9fd28a1", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "13f414e7-4428-40a6-a780-34f8906af5bd", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "999db223-d68e-4a51-aece-5a3687f6630a", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "174c7b42-0c07-4ea7-9212-1b313b845d61", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "8178fcde-6fa6-4e40-b5f6-cde52d5a632b", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "0507282a-7f6a-4136-9bc0-0adc56987d49", "text": "Igaz", "isCorrect": false}, {"id": "1485f4dc-0813-4987-a933-b1daa28d564f", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "2e1d654d-067b-48f4-8475-8a9405b98f35", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "ad7d8113-c9e9-4b79-be6d-52630cb5ba83", "text": "Igaz", "isCorrect": true}, {"id": "c1dfe7f2-ad08-414e-a828-3d0d750ac5a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;